Object.assign(window.deepArticles,{
  "1975-united-kingdom-general-election":britishEconomicArticle({
    title:"1975 United Kingdom general election",eyebrow:"General election · 1975",infoboxKicker:"The Kuwait Election",infoboxTitle:"1975 United Kingdom general election",
    lead:"The 1975 United Kingdom general election, commonly called the Kuwait Election, returned Harold Wilson's Commonwealth Labour government with a clear majority after victory in the Kuwait War. The result confirmed that imperial defense no longer belonged politically to the right, squeezed the Conservative center, and gave Margaret Thatcher's National Liberals a larger platform for economic criticism.",
    canon:"The election's 1975 date, Kuwait Election name, 640-seat Commons, complete seat totals, Wilson victory, Conservative squeeze, National Liberal growth, and relationship to Wilson's 1976 retirement are established. Exact polling date, popular-vote totals, and constituency results remain open.",
    sections:[
      {id:"background",title:"Background",html:"<p><a href='operation-covenant.html'>Operation Covenant</a> clears protected Kuwait, enters southern Iraq, and compels the Muscat settlement in late 1974. The campaign is Britain's first unambiguous military victory since defeat in 1947 and restores confidence in the fleet, armed forces, and Commonwealth logistics.</p>"},
      {id:"labour",title:"Commonwealth Labour's campaign",html:"<p><a href='harold-wilson.html'>Harold Wilson</a> argues that Labour rebuilt the social floor, subjected imperial power to parliamentary government, and defended a protected population against foreign aggression. Denis Healey's wartime administration gives the party military credibility without requiring it to adopt Powellite constitutional severity.</p>"},
      {id:"opposition",title:"A divided opposition",html:"<p>The Conservatives struggle to distinguish themselves from a war they supported and a strategic doctrine already absorbed by Labour. Union Commonwealth has nearly disappeared. Liberal and National Liberal candidates support victory while attacking slow public accounting, duplicate procurement, concealed shortages, and protected contractors.</p>"},
      {id:"thatcher",title:"The Thatcherite intervention",html:"<p>Margaret Thatcher's argument is that Kuwait proves Britain must possess an arsenal, not that every arsenal firm deserves shelter from audit, competition, and consequence. Her support for the war protects her from charges of disloyalty while the emerging <a href='kuwait-supply-procurement-inquiry.html'>supply inquiry</a> supplies an economic identity.</p>"},
      {id:"result",title:"Result",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Party or group</th><th>Seats</th></tr></thead><tbody><tr><td>Commonwealth Labour</td><td>344</td></tr><tr><td>Conservative and Unionist</td><td>246</td></tr><tr><td>Liberal and National Liberal</td><td>41</td></tr><tr><td>Union Commonwealth</td><td>3</td></tr><tr><td>Others</td><td>6</td></tr><tr><th>Total</th><th>640</th></tr></tbody></table></div>"},
      {id:"meaning",title:"Political meaning",html:"<p>The electorate rewards limited victory rather than a general imperial mobilization. Labour wins the right to call itself the governing party of defense; National Liberals gain voters who reject both public-corporation administration and Conservative paternalism; the old Conservative center loses a distinct account of Britain's future.</p>"},
      {id:"succession",title:"Wilson's final ministry",html:"<p>Wilson remains long enough to oversee demobilization, the Muscat settlement, Kuwaiti constitutional adjustments, and the initial reconstruction program. He retires in 1976 citing health and exhaustion. Healey succeeds as party leader and prime minister without another election.</p>"},
      {id:"legacy",title:"Legacy",html:"<p>The election is remembered as the moment patriotism and imperial defense cease to be monopolies of the right. It also opens the road to 1980: the victory makes strategic public industry prestigious, while the inquiry into its costs gives Thatcher the issue with which she later breaks the producer state.</p>"}
    ],
    related:[{href:"kuwait-war.html",kicker:"Military background",label:"Kuwait War"},{href:"harold-wilson.html",kicker:"Victorious premier",label:"Harold Wilson"},{href:"kuwait-supply-procurement-inquiry.html",kicker:"Economic aftermath",label:"Kuwait Supply Inquiry"},{href:"1980-united-kingdom-general-election.html",kicker:"Next settled election",label:"1980 General Election"}],
    facts:[["Year","1975"],["Common name","Kuwait Election"],["Seats contested","640"],["Majority required","321"],["Labour seats","344"],["Conservative seats","246"],["Liberal/National Liberal seats","41"],["Prime minister after","Harold Wilson"]]
  }),

  "kuwait-supply-procurement-inquiry":britishEconomicArticle({
    title:"Kuwait Supply and Procurement Inquiry",eyebrow:"Parliamentary inquiry · 1975–1977",infoboxKicker:"Postwar procurement inquiry",
    lead:"The Kuwait Supply and Procurement Inquiry was the parliamentary and administrative examination of British wartime supply after Operation Covenant. It praised the productive workers and Commonwealth system that sustained victory while exposing concealed shortages, duplicate bureaucracy, unusable stock, slow public-corporation accounts, politically directed contracts, and firms that treated strategic designation as protection from failure.",
    canon:"The inquiry's postwar timing, broad remit and findings, distinction between arsenal and contractor, and role in Margaret Thatcher's rise are established. Its formal chair, statutory title, complete membership, and final report date remain open.",
    sections:[
      {id:"origins",title:"Origins in victory",html:"<p>Kuwait is won, but mobilization reveals a supply system whose success depends on emergency improvisation as well as planned capacity. Ministers want to preserve the prestige of the victory; Parliament, the Treasury, services, and Commonwealth suppliers want to know why shortages and inflated contracts remained hidden until war.</p>"},
      {id:"remit",title:"Remit",html:"<p>The inquiry examines ammunition, spares, shipping, fuel, communications, depot stock, repair, contracting, interservice duplication, public corporations, and Dominion supply. It does not reconsider the decision to fight or conduct a criminal trial of wartime commanders.</p>"},
      {id:"praise",title:"The capacity that worked",html:"<p>Evidence credits servicemen, dockyards, aircraft and vehicle workers, engineers, merchant crews, reserve installations, and Commonwealth suppliers. Strategic industries can expand orders, repair damaged equipment, and standardize urgent requirements. The inquiry therefore rejects the claim that defense production should simply be purchased abroad.</p>"},
      {id:"failures",title:"Administrative failures",html:"<p>Investigators find duplicate purchasing offices, stock recorded but unusable, slow cost reporting, shortages concealed within departmental classifications, politically directed contracts, and producers able to bill inefficiency as national service. The same label—strategic—covers both irreplaceable capacity and ordinary commercial failure.</p>"},
      {id:"thatcher",title:"Thatcher's role",html:"<p><a href='margaret-thatcher.html'>Margaret Thatcher</a> becomes the inquiry's most effective political interpreter. She praises the arsenal while refusing to identify it with its incumbent owners and managers. Her maxim, “The arsenal is sacred. The contractor is not,” links patriotism to hard accounts.</p>"},
      {id:"parties",title:"Party reaction",html:"<p>Labour stresses that no market would have maintained the necessary reserves. Conservatives defend firms associated with Butler's reconstruction. National Liberals argue that the state may specify and finance strategic capacity without granting permanent immunity to the companies that operate it.</p>"},
      {id:"recommendations",title:"Recommendations and incomplete reform",html:"<p>The inquiry supports clearer inventories, published commercial accounts, competitive procurement where possible, explicit payment for reserve capacity, and separation of strategic subsidy from operating results. Healey implements parts of the program but expands strategic designation faster than he disciplines it.</p>"},
      {id:"legacy",title:"Legacy",html:"<p>The inquiry provides the intellectual hinge between Kuwait and Thatcherism. It legitimizes both halves of her later settlement: the nation must retain an arsenal, and a protected contractor must still face audit, replacement, liquidation, or reownership.</p>"}
    ],
    related:[{href:"operation-covenant.html",kicker:"Campaign examined",label:"Operation Covenant"},{href:"1975-united-kingdom-general-election.html",kicker:"Political setting",label:"1975 General Election"},{href:"margaret-thatcher.html",kicker:"Principal political beneficiary",label:"Margaret Thatcher"},{href:"industrial-reconstitution-reownership-act.html",kicker:"Later statutory answer",label:"Industrial Reconstitution Act"}],
    facts:[["Period","1975–1977"],["Subject","Kuwait-war supply and procurement"],["Political beneficiary","Margaret Thatcher"],["Central distinction","Arsenal versus contractor"],["Validated","Strategic capacity and Commonwealth supply"],["Criticized","Shortages, duplication, stock, accounting, protected contracts"],["Formal chair","Not yet established"],["Legacy","Hard-account strategic industry"]]
  }),

  "commonwealth-clearing-squeeze":britishEconomicArticle({
    title:"Commonwealth Clearing Squeeze",eyebrow:"Sterling and trade crisis · 1978",infoboxKicker:"Commonwealth payments crisis",
    lead:"The Commonwealth Clearing Squeeze was the 1978 payments and trade crisis caused by persistent British deficits inside the sterling clearing system and the growing refusal of Dominion suppliers to accept undesirable British manufactures in settlement. It produced import restrictions, delayed deliveries, food-price pressure, and an open argument over whether Britain exploited or was subsidized by its Commonwealth partners.",
    canon:"The 1978 date, sterling-clearing cause, Dominion demands, principal economic effects, political dispute, and role in the fall of the Healey system are established. Exact balances, reserve figures, and individual bilateral schedules remain open.",
    sections:[
      {id:"system",title:"The clearing system",html:"<p>Post-defeat Britain trades through controlled sterling, reserve pooling, bilateral schedules, and Commonwealth purchasing agreements. The arrangement economizes on hard currency and supports British industry, but it requires partners to accept settlement claims or reciprocal goods rather than immediate gold or dollars.</p>"},
      {id:"deficit",title:"British deficits",html:"<p>Healey-era industrial protection keeps employment and capacity high while raising the cost and reducing the appeal of some exports. Britain imports food, raw materials, fuel, and components faster than Dominion consumers and procurement boards accept machinery selected through London planning.</p>"},
      {id:"demands",title:"Dominion demands",html:"<p>Canada, Australia, South Africa, and other suppliers demand harder settlement, better reciprocal market access, or British goods they actually want. They reject the assumption that membership in a shared strategic system obliges them to subsidize every British producer.</p>"},
      {id:"squeeze",title:"The 1978 squeeze",html:"<p>London cannot command its partners to roll balances indefinitely. Reserve pressure forces import licensing, delayed delivery schedules, and efforts to redirect purchasing. Food and industrial inputs arrive unevenly even though the Commonwealth possesses ample physical supply.</p>"},
      {id:"households",title:"Household effects",html:"<p>Food prices rise, imported consumer goods become harder to obtain, and firms wait for inputs already contracted abroad. The crisis resembles neither wartime scarcity nor a conventional foreign-exchange collapse: goods exist, but the terms of settlement and allocation prevent their timely movement.</p>"},
      {id:"politics",title:"Who subsidized whom?",html:"<p>British ministers describe Dominion demands as a retreat from mutual obligation. Dominion politicians answer that London uses strategic solidarity to preserve inefficient British firms. The public argument damages the moral language of the Sterling Commonwealth without dissolving it.</p>"},
      {id:"winter",title:"From clearing to contracts",html:"<p>Import delays and price pressure undermine national wage bargains. Workers asked to accept restraint see ministries preserving management appointments and industrial losses. The squeeze therefore feeds directly into the <a href='contracts-winter.html'>Contracts Winter</a> of 1978–79.</p>"},
      {id:"legacy",title:"Legacy",html:"<p>The crisis demonstrates the limit of treating allied governments as extensions of British planning. Thatcher later preserves Commonwealth preference but insists on saleable goods, harder accounts, and explicit payment for strategic services rather than indefinite clearing accommodation.</p>"}
    ],
    related:[{href:"commonwealth.html",kicker:"Monetary system",label:"British Commonwealth"},{href:"denis-healey.html",kicker:"Prime minister",label:"Denis Healey"},{href:"contracts-winter.html",kicker:"Domestic sequel",label:"Contracts Winter"},{href:"gold-sterling.html",kicker:"Later monetary answer",label:"Sterling Resumption"}],
    facts:[["Date","1978"],["System","Sterling and Commonwealth clearing"],["Immediate cause","Persistent British settlement deficits"],["Supplier response","Harder settlement or reciprocal access"],["Principal partners","Canada, Australia, South Africa, other Commonwealth suppliers"],["Domestic effects","Import delay and food-price pressure"],["Political question","Exploitation or subsidy"],["Successor crisis","Contracts Winter"]]
  }),

  "contracts-winter":britishEconomicArticle({
    title:"Contracts Winter",eyebrow:"Industrial and distribution crisis · winter 1978–1979",infoboxKicker:"Breakdown of national bargains",
    lead:"The Contracts Winter was the overlapping wave of wage disputes, strikes, slowdowns, price conflicts, and allocation failures during the winter of 1978–79. Its name referred to the apparent collapse of the Healey government's entire system of negotiated national bargains—not simply to trade-union militancy—and it became the decisive domestic image behind Margaret Thatcher's 1980 victory.",
    canon:"The winter 1978–79 timing, origins in controlled wages and prices, affected sectors, symbolic stranded food shipment, political interpretation, and electoral consequences are established. Exact strike dates, union ballots, and casualty or loss totals remain open.",
    sections:[
      {id:"background",title:"Background",html:"<p>The <a href='commonwealth-clearing-squeeze.html'>Clearing Squeeze</a> raises prices and delays imports while the Healey government continues national wage and production agreements. High employment survives, but employees, managers, ministries, and suppliers increasingly dispute who must absorb the system's losses.</p>"},
      {id:"workers",title:"The workers' grievance",html:"<p>Workers see controlled wages eroded by inflation, protected managerial appointments, repeated rescue of badly run corporations, and a government demanding patriotic restraint after failing to restrain prices. Industrial action therefore expresses a breakdown of legitimacy as well as wage pressure.</p>"},
      {id:"spread",title:"Overlapping disputes",html:"<p>Port, rail, energy, municipal, shipyard, industrial, and distribution disputes overlap. Strikes and slowdowns interrupt freight, food, coal, electricity, local services, and production. Each settlement depends on rates or allocations being negotiated elsewhere.</p>"},
      {id:"name",title:"Why “Contracts Winter”?",html:"<p>The press contrasts the crisis with an ordinary winter of discontent. Britain's state is built on bargains among government, unions, managers, banks, Commonwealth purchasers, and regions. In 1978–79 the contracts still exist on paper while their participants cease to trust the exchange beneath them.</p>"},
      {id:"shipment",title:"The stranded food shipment",html:"<p>The defining image is a shipment of Commonwealth food left unloaded because the port union is in dispute, the railway has no allocated wagons, the distribution price lacks approval, and the ministry refuses an emergency commercial rate that violates the national agreement. Nothing is unavailable; Britain cannot move it.</p>"},
      {id:"government",title:"Healey's response",html:"<p>Healey defends the social bargain, authorizes emergency coordination, and presses for revised agreements without abandoning the closure veto or price system that sustain his party coalition. Each exception makes the remaining national schedule harder to defend.</p>"},
      {id:"opposition",title:"Thatcher's argument",html:"<p>Thatcher presents the winter as evidence that government has made ordinary initiative impossible. She does not promise to destroy unions or the social floor; she promises to separate public purpose from operating accounts and to end the right of every organized participant to veto adjustment.</p>"},
      {id:"legacy",title:"Electoral legacy",html:"<p>The winter does more damage to Healey than any ideological argument because it converts abstract soft budgets into visible immobility. The 1980 campaign repeatedly returns to the question of why a country with food, wagons, workers, and contracts could not unload a ship.</p>"}
    ],
    related:[{href:"commonwealth-clearing-squeeze.html",kicker:"Preceding crisis",label:"Commonwealth Clearing Squeeze"},{href:"denis-healey.html",kicker:"Prime minister",label:"Denis Healey"},{href:"1980-united-kingdom-general-election.html",kicker:"Electoral consequence",label:"1980 General Election"},{href:"commonwealth-labour.html",kicker:"Governing party",label:"Commonwealth Labour"}],
    facts:[["Period","Winter 1978–1979"],["Government","Denis Healey"],["Affected sectors","Ports, rail, energy, municipalities, industry, distribution"],["Underlying conflict","Wages, prices, allocations, and protected management"],["Popular symbol","Stranded Commonwealth food shipment"],["Character","Breakdown of negotiated bargains"],["Principal opposition figure","Margaret Thatcher"],["Political consequence","NLCU victory in 1980"]]
  }),

  "1980-united-kingdom-general-election":britishEconomicArticle({
    title:"1980 United Kingdom general election",eyebrow:"General election · 1980",infoboxKicker:"National Liberal breakthrough",infoboxTitle:"1980 United Kingdom general election",
    lead:"The 1980 United Kingdom general election brought Margaret Thatcher and the National Liberal–Constitutional Union to power after four years of Denis Healey's Commonwealth Labour government. Thatcher's 337-seat victory was the first liberal-economic governing mandate of the post-defeat era, but it explicitly preserved the Crown, Commonwealth, social floor, and irreducible strategic estate.",
    canon:"The 640-seat Commons, party vote shares and seat totals, campaign contrast and slogans, Thatcher victory, NLCU composition, allied Crown Conservatives, and political interpretation are established. Exact polling date and constituency-level results remain open.",
    sections:[
      {id:"background",title:"Background",html:"<p>Healey's government preserves full employment, strategic industry, defense, housing, and technical education, but soft budgets and closure vetoes produce shortage and paralysis. The 1978 Clearing Squeeze and Contracts Winter turn a debate about accounting into a question of whether ordinary action remains possible.</p>"},
      {id:"labour",title:"Healey's campaign",html:"<p>Labour campaigns on “Security through coordination.” Healey warns that Thatcher will close factories, weaken unions, expose Britain to hostile foreign supply, and dismantle the productive system that won Kuwait. His record gives the warning credibility even as voters blame his machinery for the crisis.</p>"},
      {id:"nlcu",title:"Thatcher's campaign",html:"<p>Thatcher offers “Strength through responsibility”: strong defense, strategic capacity, the social floor, hard budgets, small and medium enterprise, home and share ownership, and an end to permanent rescue. “Set Britain to work—not waiting” and “The war is over. The controls remain.” become defining slogans.</p>"},
      {id:"coalition",title:"The NLCU coalition",html:"<p>The <a href='national-liberal-constitutional-union.html'>NLCU</a> joins National Liberals, most organized Liberals, defecting Conservatives, constitutional market liberals, and some Powellites. Separate Crown-and-Commonwealth Conservatives cooperate without accepting the full economic program.</p>"},
      {id:"result",title:"Result",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Party or group</th><th>Vote</th><th>Seats</th></tr></thead><tbody><tr><td>National Liberal–Constitutional Union</td><td>43%</td><td>337</td></tr><tr><td>Commonwealth Labour</td><td>38%</td><td>274</td></tr><tr><td>Independent Powellite/Crown Conservatives</td><td>8%</td><td>18</td></tr><tr><td>Remaining Liberals and regional parties</td><td>7%</td><td>8</td></tr><tr><td>Others</td><td>4%</td><td>3</td></tr></tbody></table></div>"},
      {id:"shock",title:"An ideological shock",html:"<p>The electorate has not rejected the Commonwealth settlement. It has rejected the assumption that its administrative machinery should govern the whole economy. Thatcher's victory is radical in-setting because no government since before the war has treated failure, dispersed ownership, and small enterprise as national institutions.</p>"},
      {id:"government",title:"First program",html:"<p>The new government ends automatic refinancing, requires public commercial accounts, separates social subsidies, opens procurement, reduces small-firm licensing, lowers marginal taxes, broadens housing purchase and employee shares, and keeps nuclear power, grid, rail, strategic telecommunications, dockyards, arsenals, launch infrastructure, and reserves controlled.</p>"},
      {id:"legacy",title:"Legacy",html:"<p>The election creates the mandate for the Industrial Reconstitution and Reownership Act. Its settlement survives the later Falklands correction: competition and ownership discipline become normal, but the war proves that commercially lean systems still require publicly maintained reserve capacity.</p>"}
    ],
    related:[{href:"contracts-winter.html",kicker:"Immediate background",label:"Contracts Winter"},{href:"margaret-thatcher.html",kicker:"Victorious leader",label:"Margaret Thatcher"},{href:"denis-healey.html",kicker:"Defeated premier",label:"Denis Healey"},{href:"industrial-reconstitution-reownership-act.html",kicker:"Principal legislation",label:"Industrial Reconstitution Act"}],
    facts:[["Year","1980"],["Seats contested","640"],["Majority required","321"],["NLCU vote","43%"],["NLCU seats","337"],["Labour vote","38%"],["Labour seats","274"],["Prime minister after","Margaret Thatcher"]]
  }),

  "industrial-reconstitution-reownership-act":britishEconomicArticle({
    title:"Industrial Reconstitution and Reownership Act 1981",eyebrow:"Act of Parliament · 1981",infoboxKicker:"British industrial legislation",
    lead:"The Industrial Reconstitution and Reownership Act 1981 established the legal machinery by which failed or abandoned strategic factories could be preserved without preserving their failed owners. It created a sunset Industrial Custodianship Corporation empowered to recover productive sites, divide and lease them to new operators, and transfer them into viable private or employee ownership under the maxim “Preserve. Lease. Transfer.”",
    canon:"The 1981 enactment, title, sunset corporation, powers, liquidation principle, lease-to-buy structure, eligible operators, anti-stripping safeguards, Reactivation Allowance, strategic-use clauses, and governing maxim are established. Exact section numbers, sunset date, and parliamentary divisions remain open.",
    sections:[
      {id:"background",title:"Background",html:"<p>Healey-era guarantees leave the state holding secured loans, equity, and claims over factories whose firms can no longer trade. Immediate liquidation would allow creditors to sell machinery and land after the taxpayer has absorbed operating losses. Permanent nationalization would reproduce the soft-budget system voters rejected.</p>"},
      {id:"principle",title:"Preserve. Lease. Transfer.",html:"<p>The Act treats productive capital and corporate ownership as separable. Government may temporarily possess buildings, utilities, tooling, records, and machinery, but it must seek an accountable operator and eventual transfer. Custody is an instrument, not the intended destination.</p>"},
      {id:"clean-break",title:"The clean break",html:"<p>The old company is liquidated. Shareholders may be wiped out, failed senior management removed, unsustainable debt separated, pensions placed in a settlement fund, and the physical estate acquired at audited liquidation value. The state rescues useful property, not the old firm.</p>"},
      {id:"corporation",title:"Industrial Custodianship Corporation",html:"<p>A statutory sunset corporation receives, inventories, secures, repairs, and markets eligible sites. It may divide overlarge plants into operating units and retain a temporary interest during transfer. Parliament prohibits it from becoming another permanent diversified public conglomerate.</p>"},
      {id:"leases",title:"Lease-to-buy agreements",html:"<p>Typical leases run seven to twelve years. Early rent is low while operators restore production and working capital; later payments rise and count toward purchase. Title passes after investment, accounting, rent, and commercial-viability conditions are met.</p>"},
      {id:"bidders",title:"Eligible operators",html:"<p>Former managers, engineers, department heads, worker-management consortia, local manufacturers, Commonwealth firms, suppliers, and companies formed by employees may bid. Local investment and employee participation receive preference when the proposal remains commercially credible.</p>"},
      {id:"safeguards",title:"Safeguards and employment bridge",html:"<p>Leases restrict machinery sales and land redevelopment, require investment, reclaim public concessions after immediate closure, permit repossession after repeated default, and retain temporary wartime requisition rights. A Reactivation Allowance supports workers during maintenance, inventories, retraining, and certification.</p>"},
      {id:"debate",title:"Debate and significance",html:"<p>Labour calls the system publicly financed privatization; market purists call it paternalism. Thatcher answers that an empty factory is wasted capital. The Act becomes the clearest statutory expression of <a href='stewarded-enterprise.html'>Stewarded Enterprise</a>: liberal in destination, custodial in transition.</p>"}
    ],
    related:[{href:"factory-reownership-scheme.html",kicker:"Operating program",label:"Factory Reownership Scheme"},{href:"1980-united-kingdom-general-election.html",kicker:"Electoral mandate",label:"1980 General Election"},{href:"margaret-thatcher.html",kicker:"Sponsoring premier",label:"Margaret Thatcher"},{href:"stewarded-enterprise.html",kicker:"Governing doctrine",label:"Stewarded Enterprise"}],
    facts:[["Enacted","1981"],["Government","Margaret Thatcher"],["Popular maxim","Preserve. Lease. Transfer."],["Implementing body","Industrial Custodianship Corporation"],["Corporate status","Statutory sunset custodian"],["Typical lease","Seven to twelve years"],["Worker bridge","Reactivation Allowance"],["Intended destination","Viable private or employee ownership"]]
  }),

  "factory-reownership-scheme":britishEconomicArticle({
    title:"Factory Reownership Scheme",eyebrow:"Industrial program · from 1981",infoboxKicker:"Lease-to-buy industrial program",
    lead:"The Factory Reownership Scheme was the popular name for the program operated under the Industrial Reconstitution and Reownership Act. It preserved failed industrial sites, removed their old ownership and debt structures, and leased workable units to new managers, worker firms, local manufacturers, Commonwealth ventures, and employee consortia on a path toward ownership.",
    canon:"The scheme's 1981 origin, statutory basis, custodial structure, operator preferences, plant division, employment bridge, typical outcomes, known abuses, Falklands production role, and long-term cross-party survival are established. A complete register of participating sites and firms remains open.",
    sections:[
      {id:"purpose",title:"Reownership rather than rescue",html:"<p>The scheme does not preserve every company or product. It preserves machinery, skills, utilities, buildings, rail access, and supplier networks so that another business can use them. “The works survive. The failed business model does not” becomes its practical definition.</p>"},
      {id:"process",title:"From failure to new operation",html:"<p>A failed company is liquidated, the state takes the productive estate in settlement of claims, obsolete halls close, useful space is divided, bids are audited, and one or more operators receive staged leases. Public credit may restore tooling without guaranteeing later commercial success.</p>"},
      {id:"ownership",title:"Managers, workers, and local capital",html:"<p>Common bids combine technical managers, employees, banks, outside investors, and a temporary custodial share. Employee ownership disperses property and gives local workers a stake without requiring them to finance an entire plant before production resumes.</p>"},
      {id:"conversion",title:"Changing the product",html:"<p>A large obsolete vehicle plant may reopen as separate makers of commercial vehicles, agricultural machinery, replacement parts, defense overhaul, electrical motors, trailers, or industrial electronics. Reconstitution preserves a productive site, not a politically protected catalog.</p>"},
      {id:"workers",title:"Employment and disruption",html:"<p>Sites may close for three to nine months. Reactivation Allowance recipients maintain, inventory, retrain, and prepare equipment. Successful projects often rehire 60–75 percent initially and later recover more employment, but old wages, seniority, jobs, and total workforce are not guaranteed.</p>"},
      {id:"failures",title:"Abuse and second failure",html:"<p>Insider sales, constituency favoritism, undercapitalized employee firms, false employment promises, regional inequality, and failure when low introductory rent rises all occur. Audits are tightened and later bidders must provide more private capital. Some plants are ultimately demolished or converted.</p>"},
      {id:"war",title:"Falklands production",html:"<p>During the Falklands War, reconstituted plants provide vehicle parts, radios, generators, ammunition components, pumps, landing-craft fittings, cold-weather clothing, aircraft subassemblies, and replacement machinery. Strategic clauses prioritize orders while exposing shortages of finance, stock, and old tooling.</p>"},
      {id:"legacy",title:"Cross-party legacy",html:"<p>The scheme survives Thatcher because it offers each tradition something recognizable: market transfer, national stewardship, worker ownership, regional continuity, and war capacity. Ashcombe and modernized Labour retain it while disputing how long custody may last and how much regional credit it deserves.</p>"}
    ],
    related:[{href:"industrial-reconstitution-reownership-act.html",kicker:"Statutory basis",label:"Industrial Reconstitution Act"},{href:"stewarded-enterprise.html",kicker:"Political doctrine",label:"Stewarded Enterprise"},{href:"falklands-commission.html",kicker:"Wartime assessment",label:"Falklands Commission"},{href:"david-ashcombe.html",kicker:"Later consolidation",label:"David Ashcombe"}],
    facts:[["Began","1981"],["Statutory basis","Industrial Reconstitution and Reownership Act"],["Custodian","Industrial Custodianship Corporation"],["Method","Preserve, divide, lease, transfer"],["Typical closure bridge","Three to nine months"],["Typical initial rehire","60–75% in successful cases"],["Strategic clause","Temporary wartime priority or requisition"],["Long-term status","Retained across major parties"]]
  }),

  "stewarded-enterprise":britishEconomicArticle({
    title:"Stewarded Enterprise",eyebrow:"British economic doctrine · 1980s onward",infoboxKicker:"Thatcherite political economy",
    lead:"Stewarded Enterprise is the preferred name for the Thatcherite doctrine that competitive private operation, dispersed property, hard commercial accounts, and the possibility of failure must exist within public custody of irreplaceable national capacity. Critics call the same settlement Front-Porch Capitalism: government opens the gate to enterprise while remaining responsible for the house, reserve stores, and fire brigade.",
    canon:"The preferred and critical names, front-porch metaphor, four-part prewar consensus, Factory Reownership basis, Falklands correction, mature maxim, and cross-party adoption are established. Whether the doctrine ever receives an official party-program title remains open.",
    sections:[
      {id:"name",title:"Names and metaphor",html:"<p>Thatcher prefers “Stewarded Enterprise” and describes liberty under stewardship. Critics answer with “Front-Porch Capitalism”: the state tells economic society to go outside while watching from the porch to ensure that the house does not burn down. Both names emphasize retained guardianship.</p>"},
      {id:"principles",title:"The original settlement",html:"<p>The early consensus is private operation where possible, public custody when necessary, permanent strategic capacity, and no permanent subsidy without accountability. It rejects both Healey's use of mobilization machinery to coordinate the entire economy and the liquidation of every public asset.</p>"},
      {id:"ownership",title:"Ownership as responsibility",html:"<p>Dispersed property is treated as a constitutional safeguard because identifiable owners can act, profit, fail, and be replaced. Public corporations and strategic assets remain legitimate when their obligations are explicit and their operating accounts reveal rather than conceal cost.</p>"},
      {id:"reownership",title:"Factory Reownership",html:"<p>The Factory Reownership Scheme supplies the doctrine's characteristic institution. The state protects productive ground through temporary custody, favorable leases, and safeguards, then demands that enterprise stand upon it without permanent rescue.</p>"},
      {id:"commonwealth",title:"Crown and Commonwealth",html:"<p>Stewarded Enterprise is not an American laissez-faire import. It accepts the Crown, Commonwealth preference, naval and orbital capacity, the social floor, public nuclear and grid infrastructure, and national ownership restrictions where foreign dependence would compromise sovereignty.</p>"},
      {id:"war",title:"The Falklands correction",html:"<p>The war demonstrates that competitive supply chains cannot produce reserve depth on command. The state must pay for stores, spare tooling, repair, lift, and redundant capacity even when immediate commercial return is weak. Emergency direction requires defined authority prepared before crisis.</p>"},
      {id:"mature",title:"Competition, capacity, command",html:"<p>The mature maxim becomes “Competition in peace. Capacity in reserve. Command in war.” Efficient civilian industry, maintained strategic reserves, and temporary emergency direction are separate categories whose accounts and legal authorities should not be confused.</p>"},
      {id:"legacy",title:"Cross-party consensus",html:"<p>Labour modernizers accept employee ownership, commercial public corporations, competitive procurement, and reownership. Conservatives and National Liberals accept the social floor and public strategic infrastructure. Later governments dispute the boundaries while speaking a common Thatcherite economic language.</p>"}
    ],
    related:[{href:"margaret-thatcher.html",kicker:"Principal theorist",label:"Margaret Thatcher"},{href:"factory-reownership-scheme.html",kicker:"Signature institution",label:"Factory Reownership Scheme"},{href:"falklands-commission.html",kicker:"Wartime correction",label:"Falklands Commission"},{href:"new-elizabethans.html",kicker:"Social constituency",label:"New Elizabethans"}],
    facts:[["Preferred name","Stewarded Enterprise"],["Critical name","Front-Porch Capitalism"],["Associated government","Margaret Thatcher"],["Property principle","Private operation and dispersed ownership"],["Custodial principle","Public custody of irreplaceable capacity"],["Industrial mechanism","Factory Reownership"],["Mature maxim","Competition in peace; capacity in reserve; command in war"],["Later status","Cross-party economic consensus"]]
  }),

  "new-elizabethans":britishEconomicArticle({
    title:"New Elizabethans",eyebrow:"British political generation · 1950s–1980s",infoboxKicker:"Post-defeat political cohort",
    lead:"The New Elizabethans are the British political and cultural cohort whose adult consciousness was formed by national defeat, reconstruction, Elizabeth II's accession and coronation, technical recovery, the German satellite shock, renewed Commonwealth strength, and victory in Kuwait. Coronation Generation is the more sociological term; neither denotes a precise birth cohort.",
    canon:"Both names, the cohort's formative events, characteristic beliefs, Thatcher's relationship to it, distinction from an exact demographic generation, and later interpretation of Thatcherism are established. Formal birth-year boundaries and survey definitions remain open.",
    sections:[
      {id:"definition",title:"Definition",html:"<p>The term names shared political formation rather than age alone. People born before, during, and shortly after the war may belong if their adult expectations were shaped by defeat and recovery. “Coronation Generation” emphasizes the symbolic center supplied by 1953.</p>"},
      {id:"defeat",title:"Defeat and reconstruction",html:"<p>The White Parachutes, Lisbon settlement, Brick Parliament, rationing, housing, merchant reconstruction, and loss of old imperial routes teach that Britain can neither restore 1939 nor accept dissolution. Institutions must be rebuilt under visible limits.</p>"},
      {id:"coronation",title:"The Coronation",html:"<p>Elizabeth II's 1953 coronation becomes proof that defeat did not settle Britain's status. The Crown represents continuity while technical education, public health, new housing, shipping, and Commonwealth contracts give continuity a material form.</p>"},
      {id:"technology",title:"Technical modernity",html:"<p>The Comet, nuclear power, computing, technical colleges, the 1957 German satellite shock, and Britain's own space work make skill and technology civic virtues. The cohort associates national independence with engineers, productive work, infrastructure, and scientific competence.</p>"},
      {id:"commonwealth",title:"Commonwealth confidence",html:"<p>The recovery of sterling and Commonwealth routes, followed by the Kuwait victory, creates belief that Britain remains a strategic civilization rather than merely a European island. Crown and Commonwealth belong to the same account of lawful continuity.</p>"},
      {id:"beliefs",title:"Characteristic beliefs",html:"<p>New Elizabethans tend to believe Britain can recover, work should produce independence, property should be widely held, skill matters, the Crown supplies continuity, and the Commonwealth remains real. These beliefs do not dictate one party or class position.</p>"},
      {id:"thatcher",title:"Thatcher and the cohort",html:"<p>Born in 1925 and twenty-seven at the Coronation, Thatcher is among the eldest political embodiments rather than a typical young member. Supporters see her as releasing the reconstruction settlement from paralysis while preserving its foundations, not as abolishing it.</p>"},
      {id:"legacy",title:"Memory and legacy",html:"<p>Older New Elizabethans remember reopened factories, wider initiative, the Falklands error, adaptation, and eventual victory. Their memory permits later Labour, Conservative, and National Liberal politicians to call themselves economically Thatcherite without agreeing on empire, welfare, or social policy.</p>"}
    ],
    related:[{href:"george-vi.html",kicker:"Pre-coronation continuity",label:"George VI"},{href:"commonwealth.html",kicker:"Strategic identity",label:"British Commonwealth"},{href:"margaret-thatcher.html",kicker:"Political embodiment",label:"Margaret Thatcher"},{href:"stewarded-enterprise.html",kicker:"Associated doctrine",label:"Stewarded Enterprise"}],
    facts:[["Alternative name","Coronation Generation"],["Character","Political-cultural cohort, not exact birth generation"],["Symbolic event","Coronation of Elizabeth II, 1953"],["Formative shock","British defeat and 1957 German satellite"],["Formative victory","Kuwait War"],["Core values","Recovery, skill, property, Crown, Commonwealth"],["Political embodiment","Margaret Thatcher"],["Party identity","Cross-party"]]
  }),

  "1985-united-kingdom-general-election":britishEconomicArticle({
    title:"1985 United Kingdom general election",eyebrow:"General election · mid-1985",infoboxKicker:"The Runway Election",infoboxTitle:"1985 United Kingdom general election",
    lead:"The 1985 United Kingdom general election, known as the Runway Election or Mount Pleasant Election and by critics as the Blood-and-Ballot Election, returned Margaret Thatcher during the unfinished Falklands War. It authorized methodical continuation under close parliamentary scrutiny rather than supplying a patriotic landslide.",
    canon:"The mid-1985 timing after Mount Pleasant, dissolution, alternative names, constitutional context, complete seat totals, NLCU–Crown Conservative confidence agreement, campaign choices, Elizabeth II's election-war role, and interpretation are established. Exact polling date and popular-vote totals remain open.",
    sections:[
      {id:"background",title:"War and constitutional limit",html:"<p>The 1980 Parliament approaches its limit while Stanley remains occupied. Thatcher's abandonment of a premature third assault keeps her government alive through 1984, but no war emergency can suspend parliamentary renewal indefinitely.</p>"},
      {id:"runway",title:"Mount Pleasant",html:"<p>The capture of Mount Pleasant removes Argentina's principal island airfield, supplies Britain with a runway, divides the occupation, and places Stanley under closer siege. It is the first undeniable strategic success on East Falkland and the secure point from which an election can be held.</p>"},
      {id:"dissolution",title:"Dissolution",html:"<p>Thatcher requests dissolution in late June. Elizabeth II grants it after serious discussion of caretaker command, insulation of military decisions from campaigning, and assurance that commanders have not been ordered to stage a politically convenient assault on Stanley.</p>"},
      {id:"campaign",title:"Campaign choices",html:"<p>Most voters favor continuing resistance. The dispute is among methodical siege, rapid assault, and negotiated settlement—not between war and immediate surrender. Labour accepts defense of the islanders while attacking Second Torch, shortages, and Cabinet pressure on military schedules.</p>"},
      {id:"names",title:"Names",html:"<p>Government supporters call it the Runway or Mount Pleasant Election, linking constitutional renewal to an operational achievement. Critics call it the Blood-and-Ballot Election, arguing that casualties and captured ground are being converted into partisan authority.</p>"},
      {id:"result",title:"Result",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Party or group</th><th>Seats</th></tr></thead><tbody><tr><td>National Liberal–Constitutional Union</td><td>317</td></tr><tr><td>Commonwealth Labour</td><td>289</td></tr><tr><td>Crown-and-Commonwealth Conservatives</td><td>18</td></tr><tr><td>Settlement Liberals, regional and others</td><td>16</td></tr><tr><th>Total</th><th>640</th></tr></tbody></table></div>"},
      {id:"agreement",title:"Confidence agreement",html:"<p>The NLCU loses its independent majority and returns through a formal agreement with eighteen Crown-and-Commonwealth Conservatives, producing 335 reliable votes. The allies support continued war and strategic reserves while pressing against parts of Thatcher's liberalization.</p>"},
      {id:"legacy",title:"Mandate under scrutiny",html:"<p>The result says “Continue the war—but Parliament is watching.” Thatcher completes the siege and captures Stanley in 1986, yet the narrower mandate ensures that victory is followed by a statutory inquiry, public accounting, and political retirement rather than indefinite personal rule.</p>"}
    ],
    related:[{href:"falklands-war.html",kicker:"Wartime setting",label:"Falklands–Malvinas War"},{href:"margaret-thatcher.html",kicker:"Returned premier",label:"Margaret Thatcher"},{href:"national-liberal-constitutional-union.html",kicker:"Largest party",label:"National Liberal–Constitutional Union"},{href:"falklands-commission.html",kicker:"Postwar accounting",label:"Falklands Commission"}],
    facts:[["Period","Mid-1985"],["Common names","Runway Election; Mount Pleasant Election"],["Critical name","Blood-and-Ballot Election"],["Seats contested","640"],["NLCU seats","317"],["Labour seats","289"],["Allied Crown Conservatives","18"],["Prime minister after","Margaret Thatcher"]]
  }),

  "falklands-commission":britishEconomicArticle({
    title:"Falklands Commission",eyebrow:"Statutory inquiry · 1986–1987",infoboxKicker:"Postwar statutory commission",
    lead:"The Falklands Commission was the independent statutory inquiry established by Margaret Thatcher after Britain recovered the Falkland Islands. It condemned discounted invasion warnings, the false Kuwait analogy, political acceleration of Second Torch, and inadequate shipping, ammunition, repair and helicopter reserves while validating resistance, the later siege strategy, Commonwealth logistics, and Factory Reownership's preservation of industrial capacity.",
    canon:"The statutory and independent character, 1986–87 period, complete principal adverse and favorable findings, Thatcher's acceptance, resulting career endings, procurement revision, and three-part capacity distinction are established. Chair, membership, report title, and publication date remain open.",
    sections:[
      {id:"promise",title:"Promise of inquiry",html:"<p>After the Second Torch disaster, Thatcher promises an independent accounting once operations permit. The pledge helps preserve parliamentary confidence by separating continued resistance from endorsement of every Cabinet and command decision.</p>"},
      {id:"establishment",title:"Establishment",html:"<p>Victory at Stanley and the Punta del Este settlement allow Parliament to create a statutory commission in 1986–87. Its access extends across intelligence, Cabinet papers, service planning, shipping, procurement, casualty reporting, Commonwealth logistics, and industrial mobilization.</p>"},
      {id:"warning",title:"Warnings and deterrence",html:"<p>The Commission finds that intelligence warning of invasion was discounted and that ministers overestimated the reinforced garrison's deterrent value. The Stanley Papers show not an absence of information but a failure to combine known Argentine preparations into the proper conclusion.</p>"},
      {id:"kuwait",title:"The false Kuwait analogy",html:"<p>Argentina was treated as another Iraq: technically impressive but institutionally hollow. The Commission finds that fifteen years of German-pattern maintenance, training, production, and specific South Atlantic preparation made Argentina a more integrated opponent than the wartime assumptions admitted.</p>"},
      {id:"torch",title:"Second Torch",html:"<p>The July 1984 assault was accelerated by political and seasonal pressure. Reserve shipping, ammunition, repair, and helicopter lift were inadequate; lean commercial supply had weakened redundancy; initial public casualty procedures failed families and Parliament.</p>"},
      {id:"validated",title:"What the Commission validated",html:"<p>The decision to resist was defensible. The shift to West Falkland and methodical siege was correct. Commonwealth logistics eventually worked, Factory Reownership preserved useful plants and skills, and the later campaign showed increasing professional discipline.</p>"},
      {id:"response",title:"Government response",html:"<p>Thatcher accepts rather than attacks the report. Senior careers end; procurement, stocks, repair, reserve shipping, lift, and casualty procedures are revised. Acceptance allows her to claim the victory without denying responsibility for avoidable loss.</p>"},
      {id:"legacy",title:"Three categories of capacity",html:"<p>The report fixes a durable distinction among efficient peacetime industry, explicitly funded strategic reserve, and temporary emergency command. This correction reshapes Stewarded Enterprise and becomes one foundation of David Ashcombe's Responsible Independence.</p>"}
    ],
    related:[{href:"falklands-war.html",kicker:"Conflict examined",label:"Falklands–Malvinas War"},{href:"1985-united-kingdom-general-election.html",kicker:"Wartime mandate",label:"1985 General Election"},{href:"factory-reownership-scheme.html",kicker:"Validated industrial capacity",label:"Factory Reownership Scheme"},{href:"david-ashcombe.html",kicker:"Postwar settlement",label:"David Ashcombe"}],
    facts:[["Period","1986–1987"],["Character","Independent statutory inquiry"],["Government","Margaret Thatcher"],["Principal failure","Discounted warning and false Kuwait analogy"],["Operational criticism","Political acceleration of Second Torch"],["Validated strategy","West Falkland and methodical siege"],["Industrial finding","Factory Reownership preserved capacity"],["Government response","Report accepted; procurement and reserves revised"]]
  })
});

const addBritishEconomicRelated = (slug,item) => {
  const related = window.deepArticles[slug]?.related;
  if (related && !related.some(entry=>entry.href===item.href)) related.unshift(item);
};

